{"explanation":"The sine graph is wavy because sine measures the height of a point moving around a circle. As the point turns, its height rises to a peak, falls through zero to a trough, and rises again—smoothly repeating with every turn. The graph shows that height against the angle; use the slider to see how one trip around the circle makes one wave.","manimCode":"const heading = new Text({ text: 'Sine is the height of a rotating point', color: WHITE, fontSize: 29 });
heading.moveTo([-1.1, 3.15, 0]);
scene.add(heading);

const ax = new Axes({ xRange: [0, 2 * Math.PI, Math.PI / 2], yRange: [-1.5, 1.5, 0.5], xLength: 6.2, yLength: 3.75, tips: false });
ax.moveTo([1.25, -0.3, 0]);
const baseline = ax.coordsToPoint(0, 0)[1];
const centerPt = [-4.35, baseline, 0];
const radiusVal = 1.25;
const circleShape = new Circle({ radius: radiusVal, color: GRAY });
circleShape.moveTo(centerPt);
const centerDot = new Dot({ point: centerPt, color: GRAY });
const circleCaption = new Text({ text: 'Turn around the circle', color: WHITE, fontSize: 21 });
circleCaption.moveTo([-4.25, 2.05, 0]);
const graphCaption = new Text({ text: 'Record the height', color: BLUE, fontSize: 23 });
graphCaption.moveTo([1.2, 2.05, 0]);
const axisCaption = new Text({ text: 'angle:  0                         2π', color: GRAY, fontSize: 20 });
axisCaption.moveTo([1.25, -2.55, 0]);
const footer = new Text({ text: 'One full turn = one repeating wave', color: YELLOW, fontSize: 23 });
footer.moveTo([1.1, -3.15, 0]);
scene.add(ax, circleShape, centerDot, circleCaption, graphCaption, axisCaption, footer);

const theta = new ValueTracker(0);
function circlePoint() {
  const a = theta.getValue();
  return [centerPt[0] + radiusVal * Math.cos(a), baseline + radiusVal * Math.sin(a), 0];
}
function graphPoint() {
  const a = theta.getValue();
  return ax.coordsToPoint(a, Math.sin(a));
}
const orbitDot = new Dot({ point: circlePoint(), color: YELLOW });
const waveDot = new Dot({ point: graphPoint(), color: YELLOW });
const radialSegment = new Polygon({ vertices: [centerPt, circlePoint()], color: WHITE });
radialSegment.setFillOpacity(0);
radialSegment.setStrokeWidth(2);
const heightSegment = new Polygon({ vertices: [[circlePoint()[0], baseline, 0], circlePoint()], color: YELLOW });
heightSegment.setFillOpacity(0);
heightSegment.setStrokeWidth(4);
const matchingHeight = new Polygon({ vertices: [circlePoint(), graphPoint()], color: YELLOW });
matchingHeight.setFillOpacity(0);
matchingHeight.setStrokeWidth(1);
matchingHeight.setOpacity(0.35);

orbitDot.addUpdater(d => d.moveTo(circlePoint()));
waveDot.addUpdater(d => d.moveTo(graphPoint()));
radialSegment.addUpdater(p => p.setVertices([centerPt, circlePoint()]));
heightSegment.addUpdater(p => {
  const pt = circlePoint();
  p.setVertices([[pt[0], baseline, 0], pt]);
});
matchingHeight.addUpdater(p => p.setVertices([circlePoint(), graphPoint()]));
scene.add(radialSegment, matchingHeight, heightSegment, orbitDot, waveDot);

const sineCurve = ax.plot(x => Math.sin(x), { color: BLUE, xRange: [0, 2 * Math.PI], numSamples: 250 });
await scene.play(new AnimationGroup([new Create(sineCurve), theta.animateTo(2 * Math.PI)]));

const controls = new Controls(scene, { position: 'top-right', width: 230 });
controls.addSlider({ label: 'Angle (radians)', min: 0, max: 2 * Math.PI, value: 2 * Math.PI, step: 0.01, onChange: value => { theta.setValue(value); } });
makeHoverable(orbitDot, scene, { hoverScale: 1.5, hoverColor: ORANGE });
makeHoverable(waveDot, scene, { hoverScale: 1.5, hoverColor: ORANGE });
await scene.wait(999999);"}

